        ExtendedPidsPorts | ExportPointer | BitBinaries | NewFloats | Utf8Atoms |
        MapTag | BigCreation | Handshake23 | UnlinkId | V4NodeContainer;
    public const ulong Unsupported = AtomCacheHeader | Fragments | SendSender;
}

